const grid = document.getElementById('gallery-grid');
const total = 50;
const shuffled = [];
while (shuffled.length < total) {
  const copy = [...galleryImgs].sort(() => Math.random() - 0.5);
  shuffled.push(...copy);
}
shuffled.slice(0, total).forEach(function(src, i) {
  const cell = document.createElement('div');
  cell.classList.add('gallery-cell');
  const img = document.createElement('img');
  img.src = src;
  cell.appendChild(img);

  // 위에서 3번째 줄 첫번째 = 인덱스 10 (0부터 시작, 5열이므로 2*5=10)
  if (i === 10) {
    const overlay = document.createElement('div');
    overlay.style.cssText = `
      position: absolute;
      top: 0; left: 0;
      width: 100%; height: 100%;
      background: rgba(255, 0, 0, 0);
      z-index: 2;
      transition: background 0.15s ease;
    `;
    cell.appendChild(overlay);

    cell.style.cursor = 'pointer';
    cell.addEventListener('mouseenter', function() {
      overlay.style.background = 'rgba(255, 0, 0, 0.7)';
    });
    cell.addEventListener('mouseleave', function() {
      overlay.style.background = 'rgba(255, 0, 0, 0)';
    });
    cell.addEventListener('click', function() {
      overlay.style.background = 'rgba(255, 0, 0, 1)';
      setTimeout(function() {
        window.location.href = 'detail.html';
      }, 300);
    });
  }

  grid.appendChild(cell);
});